<?php namespace App\Models;use Illuminate\Database\Eloquent\Model;class VaccinationRecord extends Model{protected $fillable=['child_id','vaccine_id','hospital_id','given_on','dose_no','status','remarks'];protected $casts=['given_on'=>'date'];public function child(){return $this->belongsTo(Child::class);}public function vaccine(){return $this->belongsTo(Vaccine::class);}public function hospital(){return $this->belongsTo(Hospital::class);}}
